#include <stdio.h>
#include <stdlib.h>

#define MAXN 50005

int head[MAXN], to[2*MAXN], nxt[2*MAXN], ecnt = 0;

void addEdge(int u, int v) {
    to[ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt++;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;
    for (int i = 1; i <= N; i++) head[i] = -1;
    for (int i = 0; i < N - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        addEdge(x, y);
        addEdge(y, x);
    }

    int parent[MAXN];
    int order[MAXN];
    int stack[MAXN];
    int top = 0, ordLen = 0;

    parent[1] = 0;
    stack[top++] = 1;
    while (top > 0) {
        int u = stack[--top];
        order[ordLen++] = u;
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v == parent[u]) continue;
            parent[v] = u;
            stack[top++] = v;
        }
    }

    int down[MAXN];
    long long cnt[MAXN];
    long long globalD = 0, globalWays = 0;

    for (int i = ordLen - 1; i >= 0; i--) {
        int u = order[i];
        int maxH = 0;
        long long sumCmax = 0, sumSqCmax = 0;
        int countMax = 0;
        int hasChild = 0;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (parent[v] == u) {
                hasChild = 1;
                int h = down[v] + 1;
                long long c = cnt[v];
                if (h > maxH) {
                    maxH = h;
                    countMax = 1;
                    sumCmax = c;
                    sumSqCmax = c * c;
                } else if (h == maxH) {
                    countMax++;
                    sumCmax += c;
                    sumSqCmax += c * c;
                }
            }
        }

        if (!hasChild) {
            down[u] = 0;
            cnt[u] = 1;
            continue;
        }

        down[u] = maxH;
        cnt[u] = sumCmax;

        long long waysLocal = 0;
        int M;
        if (countMax >= 2) {
            M = 2 * maxH;
            waysLocal = (sumCmax * sumCmax - sumSqCmax) / 2;
        } else {
            int secondH = 0;
            long long sumCsecond = 1;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (parent[v] == u) {
                    int h = down[v] + 1;
                    if (h == maxH) continue;
                    long long c = cnt[v];
                    if (h > secondH) {
                        secondH = h;
                        sumCsecond = c;
                    } else if (h == secondH) {
                        sumCsecond += c;
                    }
                }
            }
            M = maxH + secondH;
            waysLocal = sumCmax * sumCsecond;
        }

        if (M > globalD) {
            globalD = M;
            globalWays = waysLocal;
        } else if (M == globalD) {
            globalWays += waysLocal;
        }
    }

    printf("%lld\n", globalD + 1);
    printf("%lld\n", globalWays);

    return 0;
}
```

